CREATE TABLE IF NOT EXISTS identity_invitations (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,requested_role TEXT NOT NULL,country_scope TEXT NOT NULL,invitation_status TEXT NOT NULL DEFAULT 'awaiting_activation' CHECK(invitation_status IN ('awaiting_activation','activated','revoked')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,activated_at TEXT);
